package pe.edu.upeu.autoandes.service.impl;
import lombok.RequiredArgsConstructor; import pe.edu.upeu.autoandes.dto.*; import pe.edu.upeu.autoandes.entity.*; import pe.edu.upeu.autoandes.exception.*; import pe.edu.upeu.autoandes.repository.*; import pe.edu.upeu.autoandes.service.service.OrdenServicioService; import org.slf4j.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class OrdenServicioServiceImpl implements OrdenServicioService { private static final Logger log=LoggerFactory.getLogger(OrdenServicioServiceImpl.class); private final OrdenServicioRepository ordenes; private final VehiculoRepository vehiculos; private final ServicioRepository servicios;
 @Transactional public OrdenResponseDTO crear(OrdenRequestDTO d,String username){if(d.detalles()==null||d.detalles().isEmpty()||d.detalles().size()>10)throw new SolicitudInvalidaException("La orden debe incluir entre 1 y 10 detalles"); Set<Long> ids=new HashSet<>();for(var x:d.detalles())if(!ids.add(x.servicioId()))throw new SolicitudInvalidaException("No se puede repetir un servicio en la misma orden");Vehiculo v=vehiculos.findById(d.vehiculoId()).orElseThrow(()->new RecursoNoEncontradoException("Vehículo no encontrado: "+d.vehiculoId()));Optional<Long> ultimo=ordenes.ultimoKilometraje(v.getId());if(ultimo.isPresent()&&d.kilometraje()<ultimo.get()){log.warn("Regla RN-04: kilometraje {} menor al último {}",d.kilometraje(),ultimo.get());throw new ReglaNegocioException("El kilometraje no puede ser menor que el último registrado: "+ultimo.get());}
 OrdenServicio o=new OrdenServicio();o.setNumero("TMP000001");o.setFecha(LocalDateTime.now());o.setVehiculo(v);o.setKilometraje(d.kilometraje());o.setEstado(EstadoOrden.REGISTRADA);o.setUsuarioRegistro(username);BigDecimal total=BigDecimal.ZERO;
 for(var item:d.detalles()){Servicio s=servicios.findById(item.servicioId()).orElseThrow(()->new RecursoNoEncontradoException("Servicio no encontrado: "+item.servicioId()));if(!s.isActivo()){log.warn("Regla RN-03: servicio inactivo {}",s.getId());throw new ReglaNegocioException("El servicio "+s.getCodigo()+" no está activo");}BigDecimal subtotal=s.getPrecio().multiply(BigDecimal.valueOf(item.cantidad()));DetalleOrden det=new DetalleOrden();det.setServicio(s);det.setCantidad(item.cantidad());det.setPrecioUnitario(s.getPrecio());det.setSubtotal(subtotal);o.agregarDetalle(det);total=total.add(subtotal);}
 o.setTotal(total);o=ordenes.saveAndFlush(o);o.setNumero(String.format(Locale.ROOT,"OS-%06d",o.getId()));o=ordenes.saveAndFlush(o);log.info("Orden registrada numero={} por {}",o.getNumero(),username);return map(o);}
 public List<OrdenResumenResponseDTO> buscar(String placa,EstadoOrden estado,LocalDate desde,LocalDate hasta){if(desde!=null&&hasta!=null&&desde.isAfter(hasta))throw new SolicitudInvalidaException("La fecha desde no puede ser posterior a hasta");LocalDateTime d=desde==null?null:desde.atStartOfDay(),h=hasta==null?null:hasta.plusDays(1).atStartOfDay();return ordenes.buscar(blankNull(placa),estado,d,h).stream().map(o->new OrdenResumenResponseDTO(o.getId(),o.getNumero(),o.getFecha(),o.getVehiculo().getPlaca(),o.getVehiculo().getCliente().getNombres(),o.getKilometraje(),o.getEstado().name(),o.getTotal())).toList();}
 public OrdenResponseDTO obtener(Long id){return map(ordenes.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Orden no encontrada: "+id)));}
 @Transactional public OrdenResponseDTO anular(Long id,String motivo){OrdenServicio o=ordenes.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Orden no encontrada: "+id));if(o.getEstado()!=EstadoOrden.REGISTRADA)throw new ReglaNegocioException("Solo se puede anular una orden REGISTRADA");if(!o.getFecha().toLocalDate().equals(LocalDate.now()))throw new ReglaNegocioException("Solo se puede anular una orden el mismo día de su registro");if(motivo==null||motivo.trim().length()<10||motivo.trim().length()>200)throw new SolicitudInvalidaException("El motivo debe tener entre 10 y 200 caracteres");o.setEstado(EstadoOrden.ANULADA);o.setMotivoAnulacion(motivo.trim());log.info("Orden anulada numero={} motivo={}",o.getNumero(),motivo.trim());return map(o);}
 private String blankNull(String s){return s==null||s.isBlank()?null:s.trim();}
 private OrdenResponseDTO map(OrdenServicio o){List<DetalleOrdenResponseDTO> ds=o.getDetalles().stream().map(d->new DetalleOrdenResponseDTO(d.getServicio().getId(),d.getServicio().getCodigo(),d.getServicio().getNombre(),d.getCantidad(),d.getPrecioUnitario(),d.getSubtotal())).toList();Vehiculo v=o.getVehiculo();return new OrdenResponseDTO(o.getId(),o.getNumero(),o.getFecha(),v.getPlaca(),v.getMarca(),v.getModelo(),v.getCliente().getNombres(),o.getKilometraje(),o.getEstado().name(),o.getTotal(),o.getUsuarioRegistro(),o.getMotivoAnulacion(),ds);}
}
